    coalesced = 0.0;
    for (i = 0; i < j; i++) {
        a = time_windows[i];
        b = time_windows[i + 1];
        if (i + 1 == j) {
            waiting_time = values[i] < a ? 0.0 : values[i] - a;
            rate = 1 / waiting_time;
        } else {
            rate = log(1 - weight[i] / (1 - coalesced)) / (a - b);
        }
        output[i] = rate > 0 ? rate : 0;
        coalesced += weight[i];
    }
    return ret;
}

